import{_ as o,a,b as r,c as n}from"./chunks/measurement_result2.D3YFY8lz.js";import{_ as s,o as e,c as i,a0 as l}from"./chunks/framework.akKRIpjQ.js";const x=JSON.parse('{"title":"02 · AI 测握把尺寸","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/02-ai-grip.md","filePath":"zh/guide/02-ai-grip.md"}'),d={name:"zh/guide/02-ai-grip.md"};function p(g,t,h,c,u,m){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_02-·-ai-测握把尺寸" tabindex="-1">02 · AI 测握把尺寸 <a class="header-anchor" href="#_02-·-ai-测握把尺寸" aria-label="Permalink to &quot;02 · AI 测握把尺寸&quot;">​</a></h1><blockquote><p>4 个功能中的第 1 个。拍一张手掌照片 → 推荐握把尺寸（Yonex L0–L5 / Wilson 英寸分数 / Head–Prince–Babolat 等效）。</p></blockquote><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><img src="'+o+'" alt="相机对准手掌" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>举起手机对准手掌，App <strong>默认在端侧</strong>（<strong>不上传</strong>）估算：</p><ul><li><strong>掌心长度</strong>（mm）</li><li><strong>手掌宽度</strong>（mm）</li><li><strong>手指数 + 比例</strong>（用于跨手型校准）</li><li>→ 同时输出三套体系的推荐尺码</li></ul><h2 id="怎么拍才准" tabindex="-1">怎么拍才准 <a class="header-anchor" href="#怎么拍才准" aria-label="Permalink to &quot;怎么拍才准&quot;">​</a></h2><h3 id="关键-1-放在平的桌面上-垫一张-a4-纸-手平放手心向上五指张开" tabindex="-1">关键 1：放在平的桌面上，垫一张 A4 纸，手平放手心向上五指张开 <a class="header-anchor" href="#关键-1-放在平的桌面上-垫一张-a4-纸-手平放手心向上五指张开" aria-label="Permalink to &quot;关键 1：放在平的桌面上，垫一张 A4 纸，手平放手心向上五指张开&quot;">​</a></h3><img src="'+a+`" alt="手掌平放在 A4 纸上" style="max-width:320px;border-radius:12px;margin:12px 0;"><blockquote><p>对，这张图本身也是调整页的截图，但同时也是<strong>拍照前你想要摆出的姿势参考</strong>——掌心朝上、五指张开、手掌平贴在纸上，AI 就能在第一遍就把掌长估准。</p></blockquote><ul><li><strong>桌面要平</strong> —— 在硬的平桌上铺一张 A4 白纸。不要掌心朝外举着拍、不要靠在软物体上。</li><li><strong>手掌平贴在纸上，五指张开</strong> —— 皮肤贴着纸给 AI 一个清晰的边缘做锚点；A4 纸的尺寸还能反推相机距离（接近 30 cm 标准工作距）。</li><li><strong>手心向上（朝相机）</strong> —— 手背朝向相机的纹理太少，AI 容易定位失败；朝上贴纸面那张纹理最丰富。</li><li><strong>手指不要弯</strong> —— 手指要自然伸直并分开，哪怕稍微用力撑着也不要蜷。</li></ul><h3 id="关键-2-光线均匀" tabindex="-1">关键 2：光线均匀 <a class="header-anchor" href="#关键-2-光线均匀" aria-label="Permalink to &quot;关键 2：光线均匀&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ✅ 好                ❌ 差</span></span>
<span class="line"><span>┌────────────┐     ┌────────────┐</span></span>
<span class="line"><span>│  白墙前    │     │  杂乱桌面   │</span></span>
<span class="line"><span>│   🖐       │     │   🖐 + 📦   │</span></span>
<span class="line"><span>│            │     │            │</span></span>
<span class="line"><span>└────────────┘     └────────────┘</span></span></code></pre></div><ul><li>光线要均匀；从窗户侧面斜射的光比顶灯直照更容易拍出阴影</li><li>光线够的话关掉闪光灯</li><li>A4 白纸还能把头顶硬光「漫射化」，又一次推荐垫纸的理由</li></ul><h3 id="关键-3-手机正上方往下拍" tabindex="-1">关键 3：手机正上方往下拍 <a class="header-anchor" href="#关键-3-手机正上方往下拍" aria-label="Permalink to &quot;关键 3：手机正上方往下拍&quot;">​</a></h3><ul><li>不要斜拍 —— 正上方俯拍</li><li>相机离纸面约 30–50 cm</li><li>用<strong>后置</strong>摄像头（前置畸变大）</li></ul><h2 id="两条修正-ai-结果的路径" tabindex="-1">两条修正 AI 结果的路径 <a class="header-anchor" href="#两条修正-ai-结果的路径" aria-label="Permalink to &quot;两条修正 AI 结果的路径&quot;">​</a></h2><p>在聊结果页长什么样之前，先讲 App 提供的<strong>两种修正模式</strong>——根据情况挑一种用：</p><h3 id="模式-1-——-在结果页拖横纹线-首选" tabindex="-1">模式 1 —— 在结果页拖横纹线（首选） <a class="header-anchor" href="#模式-1-——-在结果页拖横纹线-首选" aria-label="Permalink to &quot;模式 1 —— 在结果页拖横纹线（首选）&quot;">​</a></h3><p>这个模式允许你在照片上<strong>拖动&quot;横纹线&quot;</strong>。横纹线是 AI 估的&quot;掌心起点位置&quot;；如果高估 5 mm（往指尖方向偏），推荐尺码就会跳一档。</p><ul><li>拍完后你会看到：照片上有一条 AI 画的<strong>手腕横线</strong></li><li><strong>长按后上下拖</strong>这条线</li><li>「测量值」+「推荐尺码」面板<strong>实时</strong>联动</li><li>拖动范围限制在 AI 初始位置的 ±15 mm（避免误操作拉到离谱）</li><li>满意后点 <code>保存到历史</code></li></ul><blockquote><p>这种模式适合&quot;AI 数字大致对、只是有点偏差（通常 3–10 mm）&quot;的情况。</p></blockquote><h3 id="模式-2-——-调整页-adjust-green-frame-把-a4-纸贴着绿框" tabindex="-1">模式 2 —— 调整页（Adjust Green Frame）：把 A4 纸贴着绿框 <a class="header-anchor" href="#模式-2-——-调整页-adjust-green-frame-把-a4-纸贴着绿框" aria-label="Permalink to &quot;模式 2 —— 调整页（Adjust Green Frame）：把 A4 纸贴着绿框&quot;">​</a></h3><p>如果结果<strong>整体比例</strong>不对，比如你穿错了几层手胶让图像看着被拉长/压缩了——切到 <strong>调整页</strong> 给 App 一个已知的物理参考。</p><p>这一页的标题是 <strong>&quot;Adjust Green Frame&quot;</strong>，展示：</p><img src="`+a+'" alt="调整页 —— 把 A4 纸边缘贴着绿色矩形框" style="max-width:320px;border-radius:12px;margin:12px 0;"><ul><li>完整的拍摄照片（手掌 + A4 纸）</li><li>App 按 30 cm 标准工作距算出的一圈 <strong>青绿色矩形框</strong></li><li>底部一行提示：<strong>&quot;Drag with one finger; pinch to zoom (rotation disabled). Fit the A4 inside the green frame, then Next.&quot;</strong></li><li>一个绿色 <strong>Next (Analyze)</strong> 按钮</li></ul><p>怎么操作：</p><ul><li><strong>单指拖动</strong> —— 把照片平移，让 A4 纸整体居中到绿框里</li><li><strong>两指捏合 / 张开</strong> —— 缩放照片，让 <strong>A4 纸的四条边尽量贴着绿框</strong></li><li>让四条纸边<strong>与绿框重叠</strong>为止 —— 重合越紧，比例标定越准</li><li><strong>不允许旋转</strong>（避免你一不小心把照片转了）</li><li>对齐到满意后点 <strong>Next (Analyze)</strong> —— App 用新的比例再跑一次掌长检测</li></ul><blockquote><p>A4 纸的物理尺寸是 210 × 297 mm，告诉 App &quot;绿框 = 一张 A4 纸 + 这个工作距&quot;就把<strong>绝对比例</strong>钉死了——这是单靠模式 1 拖横纹线达不到的修正。</p><p>把这两个模式配合用：<strong>模式 2 定比例，模式 1 定掌心起点</strong>。</p></blockquote><h2 id="拍照流程" tabindex="-1">拍照流程 <a class="header-anchor" href="#拍照流程" aria-label="Permalink to &quot;拍照流程&quot;">​</a></h2><ol><li>「首页」→ <code>AI 测握把尺寸</code></li><li><code>开始测量</code> → 申请摄像头权限（首次）</li><li>手机<strong>正上方</strong>俯拍（≈ 30–50 cm 离纸面），取景框对准平放的手掌，<strong>静止 1 秒</strong>预检姿态</li><li><code>拍摄</code>（或自动触发）</li><li>等待 1–2 秒：端侧 MediaPipe Hand 检测 → 进入结果页</li></ol><h2 id="结果页" tabindex="-1">结果页 <a class="header-anchor" href="#结果页" aria-label="Permalink to &quot;结果页&quot;">​</a></h2><img src="'+r+'" alt="测量结果" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>结果页把 AI 识别结果叠加在你拍的照片上，左图右数：</p><table tabindex="0"><thead><tr><th>面板</th><th>内容</th></tr></thead><tbody><tr><td><strong>照片 + 叠加</strong></td><td>你的手掌 + AI 画的 <strong>横纹线</strong>（掌心和手腕交界处那条横线）</td></tr><tr><td><strong>测量值</strong></td><td>掌长 + 掌宽（mm）</td></tr><tr><td><strong>推荐尺码</strong></td><td>同时输出 Yonex / Wilson / Head–Prince–Babolat</td></tr></tbody></table><img src="'+n+`" alt="测量结果 —— 三家体系网格" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>三家体系网格示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             Yonex   Wilson    Head / Prince / Babolat</span></span>
<span class="line"><span>             L3      4½&quot;       4¾</span></span></code></pre></div><p><strong>横纹线位置不对？</strong> 用上面的<a href="#两条修正-ai-结果的路径">模式 1</a>，直接拖就行。</p><p><strong>横纹线压根没画出来 / 数字明显跑偏？</strong> 在结果页点 <code>仅调整缩放</code> 走模式 2。</p><h2 id="误差预算与缓解" tabindex="-1">误差预算与缓解 <a class="header-anchor" href="#误差预算与缓解" aria-label="Permalink to &quot;误差预算与缓解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误差来源</th><th>影响</th><th>缓解</th></tr></thead><tbody><tr><td>手掌<strong>角度倾斜</strong></td><td>长度 ±5–8 mm</td><td>App 提示&quot;请放平&quot;</td></tr><tr><td><strong>焦距畸变</strong>（前置摄像头明显）</td><td>长度 ±3 mm</td><td>默认强制用后置</td></tr><tr><td><strong>肤色 / 光照</strong></td><td>关键点偏移 ±2 mm</td><td>MediaPipe Hand 2024 模型在多肤色上鲁棒</td></tr><tr><td>手掌<strong>部分遮挡</strong>（戒指、长指甲）</td><td>失败 / 偏大</td><td>提前摘掉戒指、剪指甲</td></tr><tr><td>手型<strong>训练偏差</strong></td><td>±3 mm</td><td>用模式 1 拖横纹线，或模式 2 调整页滑块</td></tr></tbody></table><blockquote><p><strong>实测均方根误差</strong>：端侧 4.2 mm。 转换到档位 ≈ Yonex 体系的 <strong>±⅓ 档</strong>。</p></blockquote><h2 id="局限与边界" tabindex="-1">局限与边界 <a class="header-anchor" href="#局限与边界" aria-label="Permalink to &quot;局限与边界&quot;">​</a></h2><ul><li>❌ <strong>不支持戴手套</strong>：手套会丢关键点</li><li>❌ <strong>儿童手掌</strong>：训练集主要是成年人；儿童手掌测不准</li><li>❌ <strong>极端光线</strong>（暗光、强烈逆光）：拍不到 → 用调整页</li><li>❌ <strong>多人合影</strong>：App 自动选最大的手掌（也容易挑错）</li></ul><h2 id="不保存原图" tabindex="-1">不保存原图 <a class="header-anchor" href="#不保存原图" aria-label="Permalink to &quot;不保存原图&quot;">​</a></h2><p>V1.1 <strong>不保存</strong>拍的原图。测量完成后只缓存「关键点坐标数组」（~80 字节）用于历史回看，<strong>原图当场丢弃</strong>。如果你需要「再拍一张用作以后换算」，请到「设置 → 数据管理 → 启用原图存档」主动开启（默认关）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="iphone-ipad-能用吗" tabindex="-1">iPhone / iPad 能用吗? <a class="header-anchor" href="#iphone-ipad-能用吗" aria-label="Permalink to &quot;iPhone / iPad 能用吗?&quot;">​</a></h3><p>当前版本不支持 iOS。详见 <a href="./00-introduction.html#支持平台">00 · 支持平台</a>。</p><h3 id="端侧检测需要多大算力" tabindex="-1">端侧检测需要多大算力? <a class="header-anchor" href="#端侧检测需要多大算力" aria-label="Permalink to &quot;端侧检测需要多大算力?&quot;">​</a></h3><p>推荐 Snapdragon 7xx / 天玑 800 及以上。低端机会感觉&quot;转圈&quot;几秒。</p><h3 id="测出来的数据会上传吗" tabindex="-1">测出来的数据会上传吗? <a class="header-anchor" href="#测出来的数据会上传吗" aria-label="Permalink to &quot;测出来的数据会上传吗?&quot;">​</a></h3><p><strong>不会</strong>。所有计算都在端侧跑，图片从不离开你的手机。</p><h3 id="我不同意-ai-的结果-怎么办" tabindex="-1">我不同意 AI 的结果，怎么办? <a class="header-anchor" href="#我不同意-ai-的结果-怎么办" aria-label="Permalink to &quot;我不同意 AI 的结果，怎么办?&quot;">​</a></h3><p>按精度由高到低有两种方式：</p><ol><li><strong>结果页微调横纹线</strong> —— 长按横纹线的把手上下拖；测量值与推荐尺码实时联动。<strong>AI 数字大致对、只是有点偏差（通常 3–10 mm）时用这个</strong>。</li><li><strong>调整页</strong> —— 在结果页点 <code>仅调整缩放</code> → 一根 ±10 mm 滑块。<strong>你已经用尺子量完、只想把数字敲进 App 时用这个</strong>，或端侧检测完全失败根本看不到照片时。</li></ol>`,58)])])}const A=s(d,[["render",p]]);export{x as __pageData,A as default};
